# Check what transform_v3 actually did for demo 3 vs expected
def transform_v3_fixed(grid):
    h, w = len(grid), len(grid[0])

    horizontal_lines = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    vertical_lines = [c for c in range(w) if len(set([grid[r][c] for r in range(h)])) == 1 and grid[0][c] != 0]

    if not horizontal_lines:
        return [row[:] for row in grid]

    if not vertical_lines:
        return [row[:] for row in grid]

    bottom_h = horizontal_lines[-1]
    left_c = vertical_lines[0] - 1
    right_c_start = vertical_lines[0] + 1

    pattern_h = h - (bottom_h + 1)
    pattern_w = left_c + 1

    pattern = [grid[bottom_h + 1 + r][c] for r in range(pattern_h) for c in range(pattern_w)]
    pattern = [pattern[i*pattern_w : (i+1)*pattern_w] for i in range(pattern_h)]

    row_sections = []
    prev = -1
    for hl in horizontal_lines:
        start = prev + 1 if prev >= 0 else 0
        end = hl - 1
        if start <= end:
            row_sections.append((start, end))
        prev = hl
    if prev < h - 1:
        row_sections.append((prev + 1, h - 1))

    output = [['' for _ in range(w)] for _ in range(h)]

    for (r_start, r_end) in row_sections:
        for r in range(r_start, r_end + 1):
            pr = r - r_start
            if len(pattern) > 0:
                pr = pr % pattern_h
            else:
                pr = 0

            # Fill left section
            for c in range(left_c + 1):
                if c in vertical_lines:
                    continue  # Keep cross, use input value
                pc = c
                if pr < len(pattern) and 0 <= pc < len(pattern[pr]):
                    output[r][c] = str(pattern[pr][pc])

            # Fill right section
            for c in range(right_c_start, w):  # Note: right_c_start = 5, but we should start from 5
                pc = c - right_c_start
                if pr < len(pattern) and 0 <= pc < len(pattern[pr]):
                    output[r][c] = str(pattern[pr][pc])

    # Fill cross with values from input
    for r in horizontal_lines:
        for c in range(w):
            output[r][c] = str(grid[r][c])
    for c in vertical_lines:
        for r in range(h):
            if r not in horizontal_lines:
                output[r][c] = str(grid[r][c])

    return output

