def transform_clean_v7(grid):
    h, w = len(grid), len(grid[0])

    horizontal_lines = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    vertical_lines = [c for c in range(w) if len(set([grid[r][c] for r in range(h)])) == 1 and grid[0][c] != 0]

    if not horizontal_lines or not vertical_lines:
        return [row[:] for row in grid]

    bottom_h = horizontal_lines[-1]
    pattern_start_h = bottom_h + 1
    first_v = vertical_lines[0]
    pattern_w = first_v
    pattern_h = h - pattern_start_h

    pattern = [[grid[pattern_start_h + r][c] for c in range(pattern_w)] for r in range(pattern_h)]

    output = [row[:] for row in grid]

    section_starts = []
    prev = -1
    for hl in horizontal_lines:
        start = prev + 1 if prev >= 0 else 0
        if start < hl:
            section_starts.append((start, hl - 1))
        prev = hl
    if prev < h - 1:
        section_starts.append((prev + 1, h - 1))

    for r in range(h):
        if r in horizontal_lines:
            continue

        section_start = None
        for (s_start, s_end) in section_starts:
            if s_start <= r <= s_end:
                section_start = s_start
                break

        if section_start is None:
            continue

        pr = (r - section_start) % pattern_h

        for c in range(w):
            if c in vertical_lines:
                continue

            zone_start = 0
            for v in vertical_lines:
                if v < c:
                    zone_start = v + 1
                else:
                    break

            pc = c - zone_start
            if 0 <= pr < pattern_h and 0 <= pc < pattern_w:
                output[r][c] = pattern[pr][pc]

    return output

